// Generated by `drizzle-kit pull` against the Alembic-owned dev Supabase Postgres DB
// (2026-08-03, revision 0018_node_wave0_tables) — introspection only, never edit the
// column shapes by hand; re-run `npx drizzle-kit pull` and diff instead.
//
// Fidelity gap fixed by hand: drizzle-kit pull rendered
// `feedbackPromptState.runId`'s empty-string default as the invalid TypeScript
// `.default(')` (dropped a quote) instead of `.default('')`. The DB column really is
// `NOT NULL DEFAULT ''` (see mylibrary/db.py FeedbackPromptState.run_id). Fixed below;
// re-check this specific field if the schema is ever re-pulled.
import {
  pgTable,
  varchar,
  index,
  serial,
  text,
  json,
  doublePrecision,
  timestamp,
  uniqueIndex,
  unique,
  integer,
  numeric,
  check,
  date,
  boolean,
  foreignKey,
  jsonb,
  primaryKey,
} from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

