export const enrichJobs = pgTable(
  'enrich_jobs',
  {
    id: serial().primaryKey().notNull(),
    jobId: varchar('job_id').notNull(),
    userId: varchar('user_id').default('local').notNull(),
    // No .default() on `status`: the Alembic-owned table has NO server default
    // for it (Python's `default="pending"` is ORM-level only). Declaring one
    // here makes drizzle emit SQL `default` on insert, which Postgres rejects
    // against a NOT NULL column with no default. `progress`/`total` DID share
    // this comment until the half-star wave -- see the note on them below for
    // why they now carry .default(0) while their inserts stay explicit.
    status: varchar().notNull(),
    // Production carries DEFAULT 0 (the `0003` lineage), so the generated
    // baseline must too. This is for schema/baseline fidelity ONLY -- the
    // inserts still pass progress/total explicitly, because a
    // create_all-lineage DB and the PGlite mirror have no default and
    // omitting them is what 500'd POST /enrich/start in wave 4c-2.
    // Guarded by __tests__/enrich-job-insert.test.ts.
    progress: integer().notNull().default(0),
    total: integer().notNull().default(0),
    startedAt: timestamp('started_at', { mode: 'string' }),
    finishedAt: timestamp('finished_at', { mode: 'string' }),
    error: text(),
    leaseExpiresAt: timestamp('lease_expires_at', { mode: 'string' }),
    attempts: integer().default(0).notNull(),
    force: boolean().default(false).notNull(),
    runLimit: integer('run_limit'),
    createdAt: timestamp('created_at', { mode: 'string' }).defaultNow().notNull(),
  },
  (table) => [
    uniqueIndex('ix_enrich_jobs_job_id').using(
      'btree',
      table.jobId.asc().nullsLast().op('text_ops')
    ),
    index('ix_enrich_jobs_user_id').using('btree', table.userId.asc().nullsLast().op('text_ops')),
    uniqueIndex('uq_enrich_jobs_active_user')
      .on(table.userId)
      .where(sql`${table.status} in ('pending', 'running')`),
  ]
);

